def max_operations(N, a):
    def count_operations(x):
        count = 0
        while x % 2 == 0:
            x //= 2
            count += 1
        while x % 3 == 0:
            x //= 3
            count += 1
        return count if x == 1 else float('-inf')

    total_operations = 0
    for ai in a:
        total_operations += count_operations(ai)

    return total_operations

